insert into passages (id, text, difficulty_level, b, active) values
('d4cea0a9-10c6-4fd6-83ed-95e5859700db', 'Urban gardening, the practice of growing plants and food in cities rather than in rural farmland, has grown considerably in popularity over the past two decades. Community gardens, rooftop farms, and vertical growing systems have appeared in many cities as residents seek ways to produce fresh food close to home. Proponents point to several benefits: urban gardens can reduce the distance food travels before reaching consumers, provide green spaces that improve air quality, and give city dwellers, particularly children, a chance to learn where food comes from. Critics, however, note that urban gardening on a large scale faces significant obstacles. Land in cities is expensive and often contaminated with industrial pollutants, requiring costly soil testing and remediation before it can safely be used to grow food. Additionally, the yields from urban gardens are typically much lower than those from traditional farms, meaning that even a successful urban gardening program is unlikely to meet a city''s full food needs on its own. Despite these challenges, many city governments have begun offering incentives, such as tax breaks or reduced permit fees, to encourage residents and organizations to convert unused lots into productive garden space.', 3, 0.0, true);
insert into questions (id, type, text, passage_id, options, correct_answer, explanation, a, b, c, difficulty_level, created_by, hint, active) values
('d7484d18-44be-4683-a241-204d4adbd458', 'sentence_completion', 'The manager decided to ___ the meeting until next week due to scheduling conflicts.', NULL, '[{"id": "d", "text": "postpone"}, {"id": "a", "text": "attend"}, {"id": "b", "text": "begin"}, {"id": "c", "text": "cancel"}]'::jsonb, 0, '{"strategy": "due to scheduling conflicts = בגלל התנגשויות בלוח זמנים. מה עושים עם פגישה שיש בעיית לו''ז?", "correct_reason": "postpone = לדחות. התנגשות בלו''ז מובילה לדחיית הפגישה, לא ביטולה.", "options_analysis": ["נכון! postpone = לדחות — מתאים ל''until next week''", "attend = להשתתף — לא רלוונטי להחלטת המנהל", "begin = להתחיל — הפוך מדחייה", "cancel = לבטל — לא מתאים, ''until next week'' מרמז על דחייה לא ביטול"]}', 1.2, 0.0, 0.25, 3, 'ai', NULL, true),
('e2d0becf-ac45-460a-8d81-d69a180ae309', 'sentence_completion', 'The new employee found it difficult to ___ to the company''s fast-paced environment.', NULL, '[{"id": "d", "text": "ignore"}, {"id": "a", "text": "adapt"}, {"id": "b", "text": "resist"}, {"id": "c", "text": "escape"}]'::jsonb, 1, '{"strategy": "difficult...to = קשה ל-. מה עובד חדש צריך לעשות מול סביבה חדשה ומהירה?", "correct_reason": "adapt = להסתגל. עובד חדש צריך להסתגל לסביבה חדשה.", "options_analysis": ["ignore = להתעלם — לא פותר את הקושי", "נכון! adapt = להסתגל — מתאים לצורך התאמה לסביבה חדשה", "resist = להתנגד — לא הגיוני להתנגד לסביבת עבודה", "escape = לברוח — קיצוני מדי ולא הגיוני"]}', 1.09, 0.0, 0.25, 3, 'ai', NULL, true),
('e1aa65b9-e123-46de-8aa5-844084dfb917', 'sentence_completion', 'The government announced new measures to ___ air pollution in major cities.', NULL, '[{"id": "d", "text": "ignore"}, {"id": "a", "text": "cause"}, {"id": "c", "text": "reduce"}, {"id": "b", "text": "increase"}]'::jsonb, 2, '{"strategy": "new measures = צעדים חדשים. איזה יעד סביר לצעדי ממשלה נגד זיהום?", "correct_reason": "reduce = להפחית. צעדי ממשלה נגד זיהום נועדו להפחית אותו.", "options_analysis": ["ignore = להתעלם — סותר את קיום ''measures'' עצמם", "cause = לגרום — הפוך ממטרת הצעדים", "נכון! reduce = להפחית — מטרה הגיונית לצעדים נגד זיהום", "increase = להגדיל — הפוך ממטרת צעדים נגד זיהום"]}', 1.11, 0.0, 0.25, 3, 'ai', NULL, true),
('6fc99249-b3a2-4d8a-aa26-c2bc49e7e54c', 'sentence_completion', 'Her calm and confident manner helped to ___ the anxious patients before surgery.', NULL, '[{"id": "c", "text": "worry"}, {"id": "d", "text": "frighten"}, {"id": "b", "text": "confuse"}, {"id": "a", "text": "reassure"}]'::jsonb, 3, '{"strategy": "calm and confident manner = אופן רגוע ובטוח. מה עושה התנהגות רגועה למטופלים חרדים?", "correct_reason": "reassure = להרגיע. אופן רגוע ובטוח מרגיע מטופלים חרדים.", "options_analysis": ["worry = לדאוג — הפוך מהשפעת רוגע ובטחון", "frighten = להפחיד — הפוך מהשפעת רוגע", "confuse = לבלבל — הפוך מהשפעת בטחון", "נכון! reassure = להרגיע — מתאים לאופן רגוע ובטוח"]}', 0.93, 0.0, 0.25, 3, 'ai', NULL, true),
('d97e84c5-a500-4dcc-9469-6aafde1381e6', 'sentence_completion', 'The company had to ___ several employees due to the economic downturn.', NULL, '[{"id": "c", "text": "lay off"}, {"id": "d", "text": "hire"}, {"id": "b", "text": "promote"}, {"id": "a", "text": "reward"}]'::jsonb, 0, '{"strategy": "due to the economic downturn = בגלל המיתון הכלכלי. מה עושות חברות למיתון?", "correct_reason": "lay off = לפטר. מיתון כלכלי גורם לרוב לפיטורים.", "options_analysis": ["נכון! lay off = לפטר — תוצאה טבעית של מיתון", "hire = לגייס — הפוך ממיתון כלכלי", "promote = לקדם — לא מתאים למיתון", "reward = לתגמל — לא מתאים למיתון"]}', 0.92, 0.0, 0.25, 3, 'ai', NULL, true),
('5d030598-85da-4233-b314-944cfa68b9ae', 'sentence_completion', 'The scientist''s discovery was later ___ by other researchers using different methods.', NULL, '[{"id": "a", "text": "forgotten"}, {"id": "c", "text": "confirmed"}, {"id": "b", "text": "denied"}, {"id": "d", "text": "ignored"}]'::jsonb, 1, '{"strategy": "using different methods = בשיטות שונות. מה עושים חוקרים אחרים לגילוי כשהם בודקים אותו בשיטות אחרות?", "correct_reason": "confirmed = אישרו. בדיקה בשיטות שונות שמגיעה לאותה תוצאה מאשרת גילוי.", "options_analysis": ["forgotten = נשכח — סותר את קיום הבדיקה החוזרת", "נכון! confirmed = אישרו — מתאים לבדיקה חוזרת בשיטות שונות", "denied = הכחישו — לא מרומז מהמשפט", "ignored = התעלמו — סותר את קיום הבדיקה החוזרת"]}', 0.92, 0.0, 0.25, 3, 'ai', NULL, true),
('a36a59a0-f8de-4258-8d49-6af92fa554c9', 'sentence_completion', 'The restaurant''s popularity has ___ since it was featured on a popular cooking show.', NULL, '[{"id": "a", "text": "vanished"}, {"id": "d", "text": "stopped"}, {"id": "c", "text": "soared"}, {"id": "b", "text": "declined"}]'::jsonb, 2, '{"strategy": "featured on a popular cooking show = הוצג בתוכנית בישול פופולרית. מה קורה לפופולריות של מסעדה אחרי חשיפה כזו?", "correct_reason": "soared = זינקה. חשיפה בתוכנית פופולרית בדרך כלל מגדילה פופולריות.", "options_analysis": ["vanished = נעלמה — הפוך מהשפעת חשיפה", "stopped = נעצרה — לא מתאר שינוי בפופולריות", "נכון! soared = זינקה — תוצאה טבעית מחשיפה תקשורתית", "declined = ירדה — הפוך מהשפעת חשיפה חיובית"]}', 1.43, 0.0, 0.25, 3, 'ai', NULL, true),
('61329405-5f1c-4340-b3b3-eb987dabef45', 'sentence_completion', 'The teacher tried to ___ the students'' interest by using real-life examples.', NULL, '[{"id": "c", "text": "avoid"}, {"id": "b", "text": "reduce"}, {"id": "d", "text": "eliminate"}, {"id": "a", "text": "spark"}]'::jsonb, 3, '{"strategy": "using real-life examples = באמצעות דוגמאות מהחיים. למה מורה עושה זאת?", "correct_reason": "spark = להצית/לעורר. דוגמאות מהחיים נועדו לעורר עניין.", "options_analysis": ["avoid = להימנע — הפוך ממטרת עורר עניין", "reduce = להפחית — הפוך ממטרת שימוש בדוגמאות מעניינות", "eliminate = לחסל — הפוך ממטרת עניין", "נכון! spark = לעורר — מתאים למטרת שימוש בדוגמאות מהחיים"]}', 1.4, 0.0, 0.25, 3, 'ai', NULL, true),
('a2f89b8c-bfd3-41ba-afcf-5dd7a4390850', 'sentence_completion', 'The company''s new advertising campaign successfully ___ a younger audience.', NULL, '[{"id": "b", "text": "attracted"}, {"id": "a", "text": "ignored"}, {"id": "d", "text": "lost"}, {"id": "c", "text": "repelled"}]'::jsonb, 0, '{"strategy": "successfully = בהצלחה. מה עושה קמפיין פרסום מוצלח לקהל חדש?", "correct_reason": "attracted = משכה. קמפיין מוצלח מושך קהל חדש.", "options_analysis": ["נכון! attracted = משכה — תוצאה טבעית של הצלחה", "ignored = התעלמה — לא מתאר תוצאת הצלחה", "lost = איבדה — הפוך מהצלחה", "repelled = דחתה — הפוך מהצלחה"]}', 1.39, 0.0, 0.25, 3, 'ai', NULL, true),
('271ae30e-0ae9-481c-bc33-456a9f091d71', 'sentence_completion', 'Doctors recommend regular exercise to ___ the risk of heart disease.', NULL, '[{"id": "d", "text": "increase"}, {"id": "b", "text": "lower"}, {"id": "c", "text": "cause"}, {"id": "a", "text": "ignore"}]'::jsonb, 1, '{"strategy": "doctors recommend = רופאים ממליצים. מה מטרת ההמלצה על פעילות גופנית?", "correct_reason": "lower = להפחית. פעילות גופנית מפחיתה סיכון למחלות לב.", "options_analysis": ["increase = להגדיל — הפוך ממטרת המלצה רפואית", "נכון! lower = להפחית — מתאים למטרת המלצה בריאותית", "cause = לגרום — הפוך ממטרת ההמלצה", "ignore = להתעלם — סותר את קיום ההמלצה עצמה"]}', 1.25, 0.0, 0.25, 3, 'ai', NULL, true),
('a32c0e89-97e5-4cd6-8701-42867b07af82', 'sentence_completion', 'The negotiations were ___ after several hours of intense discussion.', NULL, '[{"id": "b", "text": "started"}, {"id": "d", "text": "avoided"}, {"id": "c", "text": "concluded"}, {"id": "a", "text": "ignored"}]'::jsonb, 2, '{"strategy": "after several hours of intense discussion = אחרי שעות דיון אינטנסיבי. מה קורה למשא ומתן אחרי דיון ארוך?", "correct_reason": "concluded = הסתיימו. דיון ארוך מוביל לרוב לסיום המשא ומתן.", "options_analysis": ["started = החלו — סותר ''after several hours'' שמרמז על תהליך שכבר התקיים", "avoided = נמנעו — סותר את קיום הדיון עצמו", "נכון! concluded = הסתיימו — מתאים לתהליך שהגיע לסיומו", "ignored = התעלמו — לא הגיוני אחרי דיון אינטנסיבי"]}', 1.47, 0.0, 0.25, 3, 'ai', NULL, true),
('637672a5-7417-4789-9ff4-9a0acb43c1b5', 'sentence_completion', 'The museum''s latest exhibit has ___ record numbers of visitors this month.', NULL, '[{"id": "d", "text": "lost"}, {"id": "c", "text": "refused"}, {"id": "b", "text": "repelled"}, {"id": "a", "text": "drawn"}]'::jsonb, 3, '{"strategy": "record numbers of visitors = מספרי שיא של מבקרים. מה עושה תערוכה מוצלחת למבקרים?", "correct_reason": "drawn = משכה. תערוכה מוצלחת מושכת מבקרים רבים.", "options_analysis": ["lost = איבדה — הפוך ממספרי שיא", "refused = סירבה — לא רלוונטי למספר מבקרים", "repelled = דחתה — הפוך ממשיכת מבקרי שיא", "נכון! drawn = משכה — מתאים למשיכת מספרי שיא"]}', 1.01, 0.0, 0.25, 3, 'ai', NULL, true),
('f95e9d3d-883a-4b31-85ff-4894fedc42f2', 'restatement', 'The company decided to invest heavily in renewable energy despite the high upfront costs.', NULL, '[{"id": "b", "text": "Even though renewable energy required a large initial investment, the company chose to invest in it heavily."}, {"id": "d", "text": "The company avoided investing in renewable energy because of the costs."}, {"id": "c", "text": "The company invested only a small amount in renewable energy."}, {"id": "a", "text": "Renewable energy had no costs associated with it."}]'::jsonb, 0, '{"strategy": "despite high upfront costs...invest heavily = למרות עלויות גבוהות...השקיעה רבות. ניגוד.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["נכון! אותה משמעות בדיוק: למרות עלות התחלתית גבוהה, השקיעה רבות", "הפוך — סותר ''decided to invest heavily''", "סותר ''invest heavily''", "סותר ''the high upfront costs''"]}', 1.21, 0.0, 0.25, 3, 'ai', NULL, true),
('232c46db-0db1-4efc-a8f7-5703d7bba9af', 'restatement', 'The novel''s ending left many readers feeling confused and unsatisfied.', NULL, '[{"id": "c", "text": "No one read the novel''s ending."}, {"id": "b", "text": "Many readers felt puzzled and dissatisfied by how the novel ended."}, {"id": "a", "text": "The novel had no ending at all."}, {"id": "d", "text": "Readers were delighted and fully satisfied with the novel''s ending."}]'::jsonb, 1, '{"strategy": "left readers feeling confused and unsatisfied = השאיר קוראים מבולבלים ולא מרוצים.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["סותר את קיום קוראים שכן הגיבו לספר", "נכון! אותה משמעות בדיוק: קוראים מבולבלים ולא מרוצים", "סותר את קיום הסוף המתואר", "הפוך — ''delighted and fully satisfied'' סותר ''confused and unsatisfied''"]}', 1.19, 0.0, 0.25, 3, 'ai', NULL, true),
('efb9890f-6ee8-4ba7-a1f0-75674052d404', 'restatement', 'The airline offered passengers a refund after the flight was delayed by six hours.', NULL, '[{"id": "b", "text": "The airline canceled all refunds for delayed flights."}, {"id": "d", "text": "Passengers received no compensation for the delay."}, {"id": "c", "text": "Following a six-hour delay, the airline gave passengers their money back."}, {"id": "a", "text": "The flight departed exactly on time."}]'::jsonb, 2, '{"strategy": "offered...refund after delayed = הציעה החזר אחרי עיכוב.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["הפוך — סותר את קיום ההחזר שתואר", "הפוך — סותר ''offered passengers a refund''", "נכון! אותה משמעות בדיוק: אחרי עיכוב, החברה החזירה כסף", "סותר ''delayed by six hours''"]}', 1.55, 0.0, 0.25, 3, 'ai', NULL, true),
('11449078-1960-43e7-9e3a-99bc366a0949', 'restatement', 'The professor''s clear explanations made a difficult subject much easier to understand.', NULL, '[{"id": "a", "text": "The professor refused to explain the subject at all."}, {"id": "c", "text": "The subject was already easy before the professor explained it."}, {"id": "b", "text": "The professor''s explanations made the subject more confusing."}, {"id": "d", "text": "Thanks to the professor''s clear explanations, a hard subject became easier to grasp."}]'::jsonb, 3, '{"strategy": "clear explanations made...easier = הסברים ברורים הפכו...קלים יותר. סיבה-תוצאה.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["סותר את קיום ההסברים המתוארים", "סותר ''a difficult subject''", "הפוך — סותר ''made...much easier to understand''", "נכון! אותה משמעות בדיוק: הסברים ברורים הפכו נושא קשה לקל יותר"]}', 1.03, 0.0, 0.25, 3, 'ai', NULL, true),
('8e9a7388-2195-43a1-a974-ddec35cba4e9', 'restatement', 'The city council postponed the vote on the new budget until further notice.', NULL, '[{"id": "c", "text": "The vote on the new budget was delayed indefinitely."}, {"id": "b", "text": "The city council approved the new budget immediately."}, {"id": "a", "text": "The vote took place exactly as scheduled."}, {"id": "d", "text": "The city council has no budget to vote on."}]'::jsonb, 0, '{"strategy": "postponed...until further notice = דחתה...עד להודעה חדשה.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["נכון! אותה משמעות בדיוק: ההצבעה נדחתה ללא מועד קבוע", "הפוך — סותר ''postponed the vote''", "הפוך — סותר ''postponed''", "סותר את קיום התקציב שעליו מצביעים"]}', 1.27, 0.0, 0.25, 3, 'ai', NULL, true),
('a02cff70-5041-4ee1-ba42-bfedf5ad6f36', 'restatement', 'The factory implemented stricter safety protocols following the accident.', NULL, '[{"id": "a", "text": "The factory removed all safety protocols after the accident."}, {"id": "b", "text": "After the accident happened, the factory adopted tougher safety rules."}, {"id": "d", "text": "The factory had no safety protocols before the accident."}, {"id": "c", "text": "No accident ever occurred at the factory."}]'::jsonb, 1, '{"strategy": "implemented stricter...following accident = יישמה נהלים מחמירים...בעקבות תאונה. סיבה-תוצאה.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["הפוך — סותר ''implemented stricter safety protocols''", "נכון! אותה משמעות בדיוק: אחרי התאונה, אימצה נהלי בטיחות מחמירים", "לא נאמר בפסקה — רק שהחמירו נהלים, לא שלא היו נהלים כלל", "סותר את קיום התאונה כולה"]}', 1.21, 0.0, 0.25, 3, 'ai', NULL, true),
('b28a0bd5-0664-4a84-9ec8-ce8ef7a8f6e7', 'restatement', 'The charity relies heavily on donations from the public to fund its programs.', NULL, '[{"id": "b", "text": "The charity has stopped all of its programs."}, {"id": "a", "text": "The charity receives no donations from the public."}, {"id": "c", "text": "Public donations are essential to funding the charity''s programs."}, {"id": "d", "text": "The charity funds itself entirely through government grants."}]'::jsonb, 2, '{"strategy": "relies heavily on donations = תלויה מאוד בתרומות.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["סותר את קיום התוכניות הממומנות", "הפוך — סותר ''relies heavily on donations''", "נכון! אותה משמעות בדיוק: תרומות ציבור חיוניות למימון", "לא נאמר בפסקה — אין אזכור למענקי ממשלה"]}', 1.3, 0.0, 0.25, 3, 'ai', NULL, true),
('f8b8052f-c4a1-4aa2-a0e1-63e3fffa6e64', 'restatement', 'The athlete''s rigorous training regimen paid off when she won the championship.', NULL, '[{"id": "c", "text": "The athlete won the championship without any training."}, {"id": "d", "text": "The athlete lost the championship despite training hard."}, {"id": "b", "text": "The athlete decided not to compete in the championship."}, {"id": "a", "text": "The athlete''s hard training led to her winning the championship."}]'::jsonb, 3, '{"strategy": "training paid off when won = אימונים השתלמו כשניצחה. סיבה-תוצאה.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["הפוך — סותר ''rigorous training regimen''", "הפוך — ''lost'' סותר ''won the championship''", "סותר ''won the championship''", "נכון! אותה משמעות בדיוק: אימונים קשים הובילו לניצחון"]}', 1.59, 0.0, 0.25, 3, 'ai', NULL, true),
('23eda3e6-c191-4930-9973-95a3af61ff49', 'restatement', 'The government''s new tax policy has sparked widespread debate among economists.', NULL, '[{"id": "d", "text": "The new tax policy has caused economists to argue extensively about it."}, {"id": "b", "text": "The tax policy was implemented without any controversy."}, {"id": "c", "text": "Economists have shown no interest in the new tax policy."}, {"id": "a", "text": "No new tax policy was ever proposed."}]'::jsonb, 0, '{"strategy": "sparked widespread debate = עוררה ויכוח נרחב.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["נכון! אותה משמעות בדיוק: המדיניות עוררה ויכוח נרחב בקרב כלכלנים", "סותר ''sparked widespread debate''", "הפוך — סותר ''sparked widespread debate''", "סותר את קיום המדיניות המתוארת"]}', 1.06, 0.0, 0.25, 3, 'ai', NULL, true),
