('3c574c45-fe66-401c-abaa-555a84c2fc82', 'reading_comprehension', 'What is the main idea of the passage?', 'd4cea0a9-10c6-4fd6-83ed-95e5859700db', '[{"id": "c", "text": "Urban gardening has grown in popularity and offers benefits despite facing real challenges"}, {"id": "b", "text": "City governments refuse to support urban gardening"}, {"id": "d", "text": "Urban gardening is illegal in most major cities"}, {"id": "a", "text": "Traditional farms produce less food than urban gardens"}]'::jsonb, 0, '{"strategy": "שאלת רעיון מרכזי — הפסקה סוקרת גידול פופולריות הגינון העירוני, יתרונותיו ומכשוליו.", "correct_reason": "הפסקה מציגה גם יתרונות וגם ביקורת מאוזנת על גינון עירוני.", "options_analysis": ["נכון! גידול הפופולריות, היתרונות והאתגרים = הנושא הכולל", "הפוך — הפסקה מתארת תמריצים ממשלתיים לעידוד גינון עירוני", "לא מוזכר בפסקה כלל", "הפוך — הפסקה אומרת שהתפוקה מגינון עירוני נמוכה יותר מחוות מסורתיות"]}', 1.43, 0.0, 0.25, 3, 'ai', NULL, true),
('5ba611cc-63b8-4977-8f44-064187af362c', 'reading_comprehension', 'According to the passage, what benefit do proponents of urban gardening point to?', 'd4cea0a9-10c6-4fd6-83ed-95e5859700db', '[{"id": "c", "text": "It guarantees lower food prices nationwide"}, {"id": "b", "text": "It can reduce the distance food travels before reaching consumers"}, {"id": "d", "text": "It eliminates the need for any traditional farming"}, {"id": "a", "text": "It requires no government involvement at all"}]'::jsonb, 1, '{"strategy": "שאלת פרט — חפש את היתרון המוזכר בפסקה.", "correct_reason": "הפסקה אומרת: ''urban gardens can reduce the distance food travels before reaching consumers''.", "options_analysis": ["לא נאמר בפסקה כלל", "נכון! נאמר במפורש בפסקה", "קיצוני מדי ולא נאמר בפסקה", "סותר את הפסקה שמתארת תמריצי ממשלה"]}', 0.91, 0.0, 0.25, 3, 'ai', NULL, true),
('3c3aad66-94fa-4a87-a5ca-f57a0459c8ab', 'reading_comprehension', 'The word "remediation" in the passage most closely means:', 'd4cea0a9-10c6-4fd6-83ed-95e5859700db', '[{"id": "c", "text": "celebration"}, {"id": "a", "text": "destruction"}, {"id": "b", "text": "the process of fixing or restoring something"}, {"id": "d", "text": "complete abandonment"}]'::jsonb, 2, '{"strategy": "אוצר מילים בהקשר — ''requiring costly soil testing and remediation''.", "correct_reason": "remediation = תיקון/שיקום.", "options_analysis": ["לא קשור למשמעות המילה", "הפוך גמור למשמעות המילה", "נכון! remediation = תיקון/שיקום", "לא מדויק — remediation הוא פעולה אקטיבית, לא נטישה"]}', 0.95, 0.0, 0.25, 3, 'ai', NULL, true),
('1be2935c-88dd-4911-8cc8-580aa177646c', 'reading_comprehension', 'According to the passage, why do critics say urban gardening faces obstacles?', 'd4cea0a9-10c6-4fd6-83ed-95e5859700db', '[{"id": "d", "text": "Because urban gardens are always illegal"}, {"id": "a", "text": "Because cities never offer any support for gardening programs"}, {"id": "c", "text": "Because city residents have no interest in gardening"}, {"id": "b", "text": "Because land in cities is expensive and often contaminated, and yields are typically lower than traditional farms"}]'::jsonb, 3, '{"strategy": "שאלת פרט — חפש את הביקורת בפסקה.", "correct_reason": "הפסקה אומרת: ''Land in cities is expensive and often contaminated...the yields from urban gardens are typically much lower than those from traditional farms''.", "options_analysis": ["לא נאמר בפסקה כלל", "סותר את הפסקה שמתארת תמריצים ממשלתיים", "סותר את כל הפסקה שמתארת עלייה בפופולריות גינון עירוני", "נכון! נאמר במפורש בפסקה"]}', 1.29, 0.0, 0.25, 3, 'ai', NULL, true),
('59762530-957f-4e78-ba82-60e7985bbce4', 'reading_comprehension', 'What have some city governments done to encourage urban gardening, according to the passage?', 'd4cea0a9-10c6-4fd6-83ed-95e5859700db', '[{"id": "a", "text": "Offered incentives such as tax breaks or reduced permit fees"}, {"id": "b", "text": "Banned all forms of urban gardening"}, {"id": "c", "text": "Required all residents to start gardens"}, {"id": "d", "text": "Increased taxes on unused city lots"}]'::jsonb, 0, '{"strategy": "שאלת פרט — חפש את הפעולה הממשלתית בפסקה.", "correct_reason": "הפסקה אומרת: ''many city governments have begun offering incentives, such as tax breaks or reduced permit fees''.", "options_analysis": ["נכון! נאמר במפורש בפסקה", "הפוך גמור ממה שנאמר בפסקה", "לא נאמר בפסקה כלל", "הפוך — הפסקה מתארת הקלות, לא העלאת מסים"]}', 1.17, 0.0, 0.25, 3, 'ai', NULL, true);